const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1200, height: 800 } });
  await page.addInitScript(() => {
    window.drawnText = [];
    const original = CanvasRenderingContext2D.prototype.fillText;
    CanvasRenderingContext2D.prototype.fillText = function(text, ...args) {
      if (String(text).startsWith('Hit for')) window.drawnText.push(String(text));
      return original.call(this, text, ...args);
    };
  });
  await page.goto('http://localhost:3000', { waitUntil: 'networkidle' });
  await page.click('#start');
  await page.selectOption('#difficulty', 'normal');
  await page.click('#go');
  await page.keyboard.down('d');
  await page.waitForTimeout(900);
  await page.keyboard.up('d');
  await page.waitForTimeout(7000);
  console.log('Observed enemy-hit messages:', await page.evaluate(() => [...new Set(window.drawnText)]));
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });
